import type { Guide } from './types';

export const guides: Guide[] = [
  {
    slug: 'first-c-program', title: 'How to Write and Run Your First C Program',
    description: 'Write a first C program, understand main and printf, and test it in Circuit’s online C compiler while saving your work locally.',
    intro: 'Your first C program should be small enough that you can explain every line. Begin with a greeting, change one thing at a time, and use the compiler’s feedback to connect source code with behavior. You do not need an account or a desktop installation to follow this guide in Circuit.',
    sections: [
      { heading: 'Start with a complete program', paragraphs: ['Open the compiler and create a program named greeting.c. A .c extension identifies C source, but a filename does not make text valid C. Replace the starter text with the complete example below. Preserve the punctuation even if it seems unfamiliar: braces group the function body, quotation marks delimit text, and semicolons end statements.', 'The first line includes the standard input/output declarations. It lets the compiler check a call to printf against the function’s declared type. The header is not the function implementation itself. The toolchain connects your call to the library implementation later.'], code: '#include <stdio.h>\n\nint main(void) {\n    printf("Hello, Circuit!\\n");\n    return 0;\n}' },
      { heading: 'Understand where execution starts', paragraphs: ['main is the entry function in this hosted C environment. int says that it returns an integer status, and void inside the parentheses says that this version takes no parameters. Execution enters the braces, performs the printf call, and reaches return. A return value of zero conventionally reports success to the environment.', 'The characters \\n inside the string form an escape sequence for a newline. They are not printed as a backslash and the letter n. Spaces inside the quotation marks are output; indentation outside them is for people reading the source. Consistent indentation makes nested code much easier to understand later.'] },
      { heading: 'Compile, then observe the terminal', paragraphs: ['Press Run code or Ctrl/Cmd + Enter. Circuit downloads its compiler assets on the first run, compiles C into WebAssembly in a worker, and executes the result locally. The terminal reports compilation problems or displays the program’s output and final status. A first run may take longer than later runs because of the download.', 'You should see Hello, Circuit! followed by a successful exit. The terminal’s status is separate from text written by your program. Do not add status messages to your source just to match the surrounding interface. If the compiler rejects the source, there is no new executable to run; fix that diagnostic first.'] },
      { heading: 'Make a controlled change', paragraphs: ['Change the greeting to your own short sentence and run again. Next add a second printf statement before return. Predict whether its text starts on a new line, then test that prediction. Removing the first \\n joins the two pieces of output onto one line; putting a newline back separates them.', 'Try storing a small integer in a variable and printing it with printf("Score: %d\\n", score). The %d conversion expects an int value as the next argument. Do not put score inside the quotation marks unless you want the literal word. This distinction between text and evaluated expressions appears throughout C.'] },
      { heading: 'Read an error without starting over', paragraphs: ['Temporarily remove the semicolon after printf. The compiler will usually indicate where a semicolon was expected, sometimes on the following line. Read the earliest diagnostic, inspect the line above it as well, restore the punctuation, and compile again. One missing token can produce several later messages that disappear together.', 'An error prevents a build; a warning identifies something worth checking even when compilation succeeds. Neither is the same as a wrong answer from a valid program. For example, printing 2 + 2 while labeling it as multiplication compiles correctly but contains a logic mistake. Compare actual output with a prediction, not just the success badge.'] },
      { heading: 'Keep your work and choose the next exercise', paragraphs: ['Circuit autosaves programs in this browser’s IndexedDB storage. Wait for Saved locally before leaving. Download a .c file for an individual program, or Export all for a library backup. Closing a tab only closes that editor view; deleting a program removes the saved entry. A different browser, device, or site domain has a separate library.', 'Before moving on, explain the header, main, printf, newline, and return in your own words. Then open Add Two Numbers to learn input. Keep the greeting as a working reference and create a new program for experiments. Small independent examples make it easier to identify which new concept caused a problem.'] },
    ], related: ['printf-and-scanf', 'common-compiler-errors'], example: 'hello-world',
  },
  {
    slug: 'how-a-c-compiler-works', title: 'How a C Compiler Works',
    description: 'Understand how a C compiler reads source, checks types, generates code, and works with a linker and runtime, including Circuit’s browser-based approach.',
    intro: 'A C compiler translates source into a lower-level representation that an execution environment can use. It also rejects many invalid programs along the way. Thinking of it as a set of cooperating stages explains why a spelling mistake, a missing library definition, and a runtime failure produce very different messages.',
    sections: [
      { heading: 'Characters become meaningful tokens', paragraphs: ['The compiler first needs to identify the pieces of the language: keywords such as int, identifiers such as total, punctuation, operators, and literals. These pieces are called tokens. Whitespace usually separates or formats tokens; it is not a sequence of commands for the computer. Comments are useful documentation but do not become executable instructions.', 'Preprocessing handles directives such as #include and #define before ordinary C semantics are checked. Header inclusion provides declarations and macro definitions. A macro replacement is a token transformation, not a function call with ordinary type checking and parameter evaluation rules.'] },
      { heading: 'Syntax forms a tree', paragraphs: ['Parsing determines how tokens fit the grammar. In a + b * c, multiplication belongs inside the right side of addition because of operator precedence. Parentheses can change that structure. A missing closing brace means the parser cannot complete the intended structure, even if the individual words are valid.', 'The result is often represented as an abstract syntax tree. You do not need to inspect that tree to write C, but the idea is helpful: the compiler reasons about structured expressions and declarations rather than interpreting one visual line at a time. Splitting an expression over multiple lines normally does not change its meaning.'] },
      { heading: 'Meaning and types are checked', paragraphs: ['Semantic analysis connects identifier uses with declarations and checks the operations permitted by their types. A variable must be declared in scope. A function call needs a compatible declaration. Trying to access a nonexistent structure member is different from a missing semicolon: the syntax may be recognizable, but the requested operation has no valid meaning.', 'Not every dangerous operation can be rejected. A pointer type does not prove that its current address refers to a live object. An array index calculated from input may or may not be in range. The compiler performs the checks it can, while the programmer remains responsible for contracts that depend on runtime values.'], code: 'int count = 3;\nint total = count * 4;  /* A valid int expression. */\n/* total.missing = 1; would be invalid: total is not a struct. */' },
      { heading: 'Intermediate code separates language and machine', paragraphs: ['Many compilers translate a checked program into an intermediate representation before producing target code. LLVM-based Clang uses LLVM infrastructure for this work. A shared intermediate representation lets the implementation support several source languages and several targets without a completely separate compiler for every combination.', 'Optimization can simplify computations, eliminate unused work, and transform loops while preserving the behavior promised by the language for valid programs. It is not permission to preserve accidents of undefined behavior. A program that writes outside an array has already broken the rules on which those transformations rely.'] },
      { heading: 'Code generation is not the whole application', paragraphs: ['Code generation selects operations for a target, such as native machine instructions or WebAssembly instructions. Separately compiled pieces still need to be connected. The linker resolves references between your program, startup code, and libraries. Declaring printf tells the compiler its interface; linking supplies the implementation used by the final program.', 'An undefined-symbol error often means a declaration was available but a matching definition was not. Rewriting valid syntax will not fix a missing implementation. Likewise, an operating-system-specific function may simply not exist in a browser’s WASI environment, even though the same source builds on a desktop.'] },
      { heading: 'What Circuit adds around the compiler', paragraphs: ['Circuit uses a WebAssembly build of Clang and a WASI runtime. The editor, local program library, terminal, and worker lifecycle are the product around that toolchain. The browser downloads compiler files, but your source is compiled on your device. Circuit is not a remote GCC service and does not pretend to implement a new compiler.', 'The generated program then executes in a worker. Standard input comes from the terminal, and output is returned to the visible terminal. A successful compile only proves that this translation completed; it does not prove the algorithm is correct. Test ordinary values, boundaries, and failure paths separately.'] },
      { heading: 'Use the stages to debug efficiently', paragraphs: ['Ask when the failure happened. A syntax or type message belongs to translation. An unresolved function belongs to linking. A trap, timeout, or incorrect answer after execution begins belongs to runtime behavior. Classifying the stage narrows the search before you change any code.', 'A useful experiment is to compare three tiny failures: remove a semicolon, call a declared function with no definition, and write a loop that never changes its condition. Observe the different messages, then stop the loop. Keep the versions separate so each run tests only one hypothesis.'] },
    ], related: ['c-compilation-process', 'compiler-vs-interpreter', 'common-compiler-errors'], example: 'function',
  },
  {
    slug: 'c-compilation-process', title: 'C Compilation Process Explained',
    description: 'Follow preprocessing, compilation, assembly, linking, and execution, with practical GCC stage commands and Circuit differences.',
    intro: 'The command commonly called “compile” often coordinates several tools. A source file can pass through preprocessing, compilation, assembly, and linking before it is ready to execute. Learning what each stage consumes and produces helps you diagnose build failures without treating every message as a syntax error.',
    sections: [
      { heading: 'A translation unit begins with source', paragraphs: ['A .c file plus the declarations and other text brought in through its includes forms a translation unit after preprocessing. In a larger project, each source file can be translated separately. Headers normally describe shared interfaces; source files normally provide the corresponding definitions.', 'For a first experiment, use a single file named main.c that includes stdio.h and calls puts("Ready"). Circuit works with this single-source model. Desktop projects can have many translation units, a build system, external libraries, and target-specific configuration beyond the scope of the browser workspace.'], code: '#include <stdio.h>\nint main(void) {\n    puts("Ready");\n    return 0;\n}' },
      { heading: 'Preprocessing expands directives', paragraphs: ['The preprocessor handles header inclusion, conditional compilation, and macro replacement. A missing header can stop progress here before the compiler has checked the function body. Including a header does not automatically mean a matching external library is installed or will be linked.', 'With a desktop GCC installation, gcc -E main.c writes preprocessed source to standard output. It can be surprisingly large because standard headers contain many declarations. Inspecting it is useful when a macro or #if branch behaves unexpectedly, but beginners rarely need to read every expanded header line.'] },
      { heading: 'Compilation produces target assembly', paragraphs: ['The compiler checks syntax and meaning, then translates the program for a selected target. gcc -S main.c normally writes an assembly file without completing linking. Its contents depend on the target architecture, compiler version, and optimization settings, so copying a particular instruction listing is not a portable C lesson.', 'At this stage a call to a function can refer to an implementation that will arrive later. A declaration is enough to check the call’s interface. It is not enough to make the final executable complete. This distinction is why a build can pass compilation but fail during linking.'] },
      { heading: 'Assembly creates an object file', paragraphs: ['An assembler converts assembly into an object file containing target code and metadata. gcc -c main.c normally produces main.o while stopping before linking. An object file is a building block; it is not usually a runnable program by itself.', 'For a multi-file project, each .c file can produce its own object. If only one source file changes, a build system may recompile that part and relink the results. Header changes can affect several translation units, which is why correct dependency tracking matters as projects grow.'] },
      { heading: 'Linking resolves the pieces', paragraphs: ['The linker combines objects, startup support, and needed libraries. gcc main.o -o greeting asks the driver to produce an executable named greeting. Calling a function that has only been declared but never defined commonly produces an undefined-reference diagnostic at this stage.', 'Multiple definitions are a different problem: two objects may both provide the same externally visible function or variable. Putting ordinary function definitions in a shared header can cause that mistake. Fix ownership of the definition rather than hiding the diagnostic or adding random compiler flags.'], code: '/* Desktop shell commands, not C source: */\n/* gcc -E main.c           preprocessing */\n/* gcc -S main.c           produce assembly */\n/* gcc -c main.c           produce an object */\n/* gcc main.o -o greeting  link an executable */' },
      { heading: 'Execution is a separate step', paragraphs: ['On a compatible desktop system, you launch the resulting executable through the shell or an IDE. The runtime arranges startup and eventually calls main. Input files, terminal state, memory availability, and operating-system behavior now matter in ways that were not fully determined during translation.', 'A zero exit status conventionally signals success. A nonzero status may be an intentional response to invalid input, not necessarily a crash. Conversely, a program can exit with zero and print the wrong answer. Build success, exit success, and algorithm correctness are three different questions.'] },
      { heading: 'How the stages map to Circuit', paragraphs: ['Circuit runs Clang and its linker locally in a Web Worker and targets WebAssembly with WASI support. It does not expose a shell for entering gcc commands. Put only C source in the editor and use Run. The terminal combines compiler diagnostics with the eventual execution output.', 'The browser target has different environmental capabilities from a native desktop executable. There is no arbitrary access to your disk, processes, or network through ordinary operating-system APIs. If a desktop example depends on those facilities, first determine whether the missing feature is environmental; changing valid C syntax will not add it.'] },
    ], related: ['how-a-c-compiler-works', 'online-compiler-vs-gcc'], example: 'hello-world',
  },
  {
    slug: 'printf-and-scanf', title: 'printf() and scanf() in C',
    description: 'Use formatted output and interactive input correctly, check scanf results, and avoid common whitespace and buffer mistakes.',
    intro: 'printf writes formatted output, while scanf converts input text into typed values. Their similar-looking format strings hide an important difference: printf usually receives values, and scanf usually receives addresses where converted values should be stored. Understanding that difference prevents many beginner crashes.',
    sections: [
      { heading: 'Print values with matching conversions', paragraphs: ['Include stdio.h before using either function. In printf("Count: %d\\n", count), ordinary characters are printed directly and %d converts the following int argument. Use %f for a double, %c for a character value, %s for a null-terminated character string, and %zu for size_t. Write %% to print a literal percent sign.', 'A format string is a contract with the argument list. The number and types of the arguments must match the conversions. A mismatched conversion can cause undefined behavior rather than a helpful automatic conversion. Compiler warnings catch many constant-format mistakes, so read them even if the run button remains available.'] },
      { heading: 'Read into existing objects', paragraphs: ['Declare a variable, display a prompt, then give scanf its address. For an int number, &number has the pointer type needed by %d. Leaving out the ampersand passes an integer value where an address is required. That is not a small formatting mistake: it can make the function write to an invalid location.', 'Always check the number of successful assignments returned by scanf. A single %d conversion should return 1. If it returns zero, the next input does not match an integer; if input ends before a conversion, it may return EOF. Do not use an uninitialized variable after a failed conversion.'], code: '#include <stdio.h>\nint main(void) {\n    int number;\n    printf("Number: ");\n    if (scanf("%d", &number) != 1) {\n        fputs("Expected an integer.\\n", stderr);\n        return 1;\n    }\n    printf("You entered %d\\n", number);\n    return 0;\n}' },
      { heading: 'Enter several responses naturally', paragraphs: ['In Circuit, click Run and type in the terminal when the program requests input. A prompt without a newline leaves the response on the same line. Enter submits the line; the next prompt appears after it, and keyboard focus stays in the terminal. Repeated scanf calls communicate with the same running program.', 'The interface echoes the submitted line for you. Your C program does not need to print the input again merely to show what was typed. Values can also be supplied on one line when the format accepts whitespace between them. A format with two integer conversions must return 2 before you use both variables.'] },
      { heading: 'Understand whitespace before guessing at fixes', paragraphs: ['Most numeric conversions skip leading whitespace. %c does not: it reads the next character, which may be the newline left after a previous number. scanf(" %c", &choice) adds leading whitespace to skip such separators before reading the character. That is useful for a menu choice, but inappropriate if a space itself is meaningful input.', 'Avoid ending an interactive numeric format with a newline, such as "%d\\n". Whitespace in a scanf format means consume any amount of input whitespace; it may wait for a later non-whitespace character before the call finishes. This can look like a frozen terminal even though the function is following its format.'] },
      { heading: 'Strings and floating-point values need care', paragraphs: ['For char name[32], scanf("%31s", name) leaves room for the final null terminator. The array expression already supplies an address; a plain string conversion stops at whitespace and will not read a full name containing spaces. An unbounded %s can overrun the buffer. Prefer fgets for a whole line.', 'For scanf, %f expects float * and %lf expects double *. For printf, float arguments are promoted to double, so %f prints either ordinary float or double values. These are separate function contracts. Memorizing one format table and applying it blindly to both functions is a common source of mistakes.'] },
      { heading: 'Handle input as an operation that can fail', paragraphs: ['A failed numeric conversion leaves the offending text unread. Repeating the same scanf call in a loop without consuming or replacing that input repeats the failure. For a beginner exercise, report the problem and return a nonzero status. For a robust interactive parser, read a bounded line with fgets and convert it using strtol, checking the end pointer and range.', 'scanf is suitable for controlled exercises, but converting an arbitrarily large number into a smaller integer type is not a safe validation strategy. Choose explicit bounds, test invalid text, and decide what the program should do on end-of-input. In Circuit, stdin waits have a separate idle limit, so a pause to type does not consume the normal active execution allowance.'] },
    ], related: ['first-c-program', 'pointers-for-beginners', 'common-compiler-errors'], example: 'multiplication-table',
  },
  {
    slug: 'arrays-in-c', title: 'Arrays in C',
    description: 'Learn array bounds, iteration, length, function parameters, strings, and multidimensional arrays through small C examples.',
    intro: 'An array stores a fixed number of elements of one type in contiguous storage. It is useful when several values belong to the same collection, such as scores or daily measurements. C gives you direct indexing but does not automatically protect every access, so knowing the array’s length is part of using it correctly.',
    sections: [
      { heading: 'Declare and initialize a collection', paragraphs: ['int scores[4] reserves four int elements. Adding an initializer, such as {12, 8, 15, 5}, gives each element a starting value. You can omit the size when an initializer determines it: int scores[] = {12, 8, 15, 5}. A partially initialized array fills its remaining elements with zero.', 'An automatic local array declared without an initializer does not start with useful known values. Reading an element before assigning it is a bug. When you want an all-zero integer array, int counts[10] = {0} expresses that intention directly. Do not rely on a previous run appearing to leave zeroes in memory.'] },
      { heading: 'Indexes start at zero', paragraphs: ['For four elements, valid indexes are 0, 1, 2, and 3. scores[0] refers to the first element and scores[3] to the last. scores[4] is outside the array even though the declared length is four. The length counts elements; it is not the last legal index.', 'A loop should express that relationship clearly: begin at zero and continue while i < count. Using <= visits one extra location. C may not report that mistake immediately. It can corrupt another value, trap later, or appear to work, and none of those outcomes makes the access valid.'], code: 'int scores[] = {12, 8, 15, 5};\nsize_t count = sizeof scores / sizeof scores[0];\nint total = 0;\nfor (size_t i = 0; i < count; ++i) {\n    total += scores[i];\n}\nprintf("Total: %d\\n", total);' },
      { heading: 'Keep length separate from capacity', paragraphs: ['sizeof scores gives the size of the whole array in bytes where scores is actually an array. Dividing by sizeof scores[0] gives its element count. size_t is the unsigned type used for object sizes; print it with %zu. This expression is convenient for fixed arrays defined in the same scope.', 'Capacity is how many elements storage can hold. Logical length is how many currently contain meaningful data. An input buffer with room for one hundred measurements may currently contain only six. Algorithms should process the logical length and check capacity before appending another element. Confusing the two can read uninitialized values.'] },
      { heading: 'Functions need a length argument', paragraphs: ['An array parameter such as int values[] is adjusted to a pointer parameter. The function does not receive an independent array object with its length attached. sizeof values inside that function measures the pointer, not the caller’s array. Pass the count explicitly whenever the function needs it.', 'A read-only operation can accept const int values[] to express that it will not modify elements through this parameter. A function can still receive a wrong count, so caller and callee must agree on the contract. const protects against certain writes; it does not validate pointer lifetime or bounds.'], code: 'int sum(const int values[], size_t count) {\n    int total = 0;\n    for (size_t i = 0; i < count; ++i) total += values[i];\n    return total;\n}' },
      { heading: 'Strings are arrays with a convention', paragraphs: ['char name[] = "Circuit" stores seven visible characters and a terminating null byte, so the array occupies eight bytes. String functions look for that terminator. It is different from the digit character \'0\' and different from a newline. A character array without an in-bounds terminator is not a valid C string for functions that expect one.', 'When reading text, reserve space for the terminator and use bounded input. fgets(buffer, sizeof buffer, stdin) is useful for a line in a real array scope. It can retain the newline if there is room. A byte count is also not necessarily a count of displayed Unicode characters.'] },
      { heading: 'Use dimensions deliberately', paragraphs: ['int grid[2][3] describes two rows with three integers in each row. grid[row][column] selects an entry. Nested loops mirror the dimensions, with row < 2 and column < 3. Each row has a fixed size known from the type, which matters when passing multidimensional arrays to functions.', 'Start testing with distinctive values rather than repeated zeroes: a transposed index can be invisible in uniform data. Exercise the first and last elements, then try a one-element array where appropriate. For input-driven indexes, reject negative or too-large values before accessing storage. Bounds checks belong before the operation, not after a suspicious result.'] },
    ], related: ['pointers-for-beginners', 'functions-in-c', 'segmentation-fault'], example: 'array-sum',
  },
  {
    slug: 'functions-in-c', title: 'Functions in C',
    description: 'Define C functions with clear parameters, return values, scope, pointer contracts, and small tests.',
    intro: 'Functions divide a program into operations with named interfaces. A useful function does one understandable job and tells its caller what information it needs and what it returns. You can then reason about a calculation without repeatedly mixing it with prompts, input parsing, and output formatting.',
    sections: [
      { heading: 'Start with a small calculation', paragraphs: ['int square(int value) declares a function named square that accepts one int and returns an int. Inside its body, return value * value computes the result and ends that call. main can print the result, compare it, or pass it to another function.', 'Keeping calculation separate from printing makes the function reusable. A function that always prints an answer is harder to use as part of another expression or to test without inspecting terminal text. For a first example, use small input values whose squares fit in int; the type does not promise unlimited arithmetic.'], code: '#include <stdio.h>\nint square(int value) {\n    return value * value;\n}\nint main(void) {\n    int result = square(7);\n    printf("%d\\n", result);\n    return 0;\n}' },
      { heading: 'Declarations describe the interface', paragraphs: ['The compiler must know a function’s declaration before checking a call. Placing the complete definition before main is one approach. Alternatively, write a prototype such as int square(int value); before main and put the definition later. The prototype ends with a semicolon; the definition supplies a body.', 'Return types and parameter types must agree between declarations and definitions. A header commonly shares these declarations across source files in a desktop project. Circuit’s single-source workspace can keep the prototypes and definitions together. Do not confuse declaring a function with actually implementing it: an absent definition can fail at link time.'] },
      { heading: 'Arguments are passed by value', paragraphs: ['When you call square(number), the parameter receives a copy of number’s value. Assigning a new value to that parameter does not change number in the caller. Local variables also belong to a particular call and are not directly visible to other functions.', 'This rule still applies when the argument is a pointer: the address value is copied. Dereferencing that copied address can access the caller’s object, which is how functions such as scanf write results. C does not secretly switch to a separate pass-by-reference mechanism for pointer parameters.'] },
      { heading: 'Use return values and status deliberately', paragraphs: ['A function returning void does not provide a value to use in an expression. A non-void function should return a suitable result on every relevant path. Falling through accidentally can produce undefined behavior when the caller uses the missing result. main has special rules, but copying that exception into ordinary functions is a mistake.', 'When an operation can fail, design a way to report failure without confusing it with a valid answer. One option is a status return with a pointer output parameter. Another is a result structure. For a beginner input helper, a simple success/failure return is often clearer than a global error variable.'] },
      { heading: 'Write contracts for pointer and array parameters', paragraphs: ['A function receiving an array also needs a count unless its interface uses another explicit boundary, such as a null-terminated string. A pointer alone does not reveal the number of valid elements. State whether the function reads or writes the data and whether a null pointer is permitted.', 'Never return the address of an ordinary automatic local variable. Its lifetime ends when the function returns, leaving the caller with an invalid address. Returning an int value is safe because the value is copied. Returning a pointer requires storage with a lifetime that continues long enough for the caller’s intended use.'] },
      { heading: 'Recursion needs more than a base case', paragraphs: ['A recursive function calls itself on a smaller or otherwise simpler problem. It needs a stopping case and progress toward that case. A factorial function that always calls itself with the same n has a base case in its source but never reaches it for other inputs.', 'Each active call needs execution state, commonly stored on a stack. Deep recursion can exceed the available stack before finishing, even when the algorithm is mathematically correct. Circuit sets a one-megabyte program stack. Prefer a loop for simple counting exercises and reserve recursion for problems where its structure genuinely helps.'] },
      { heading: 'Test the interface independently', paragraphs: ['Call the function with several known inputs before adding interactive input. For square, test zero, one, a negative small number, and a positive small number. Then integrate scanf while preserving the same function. This separates input parsing bugs from calculation bugs.', 'Choose names that describe the result or action, avoid hidden global state when a parameter will do, and keep assumptions visible. A short function with an undocumented range can be more dangerous than a longer one with checked inputs. A good interface makes misuse easier to notice at the call site.'] },
    ], related: ['pointers-for-beginners', 'arrays-in-c', 'common-compiler-errors'], example: 'function',
  },
  {
    slug: 'pointers-for-beginners', title: 'Pointers in C for Beginners',
    description: 'Understand addresses, dereferencing, pointer lifetime, arrays, const, and safe pointer-based updates in C.',
    intro: 'A pointer is a value used to refer to an object or function. For beginner C, start with pointers to ordinary variables: identify the object, obtain its address, and access it only while that object exists. You do not need manual allocation to understand this core idea.',
    sections: [
      { heading: 'Connect a pointer to a real object', paragraphs: ['int number = 10 creates an integer object. int *pointer = &number creates a pointer initialized with that object’s address. The ampersand takes an address. In an expression, *pointer dereferences the pointer to access the object it designates.', 'The star has different roles in a declaration and an expression. In int *pointer it helps describe the type; in *pointer = 20 it selects the pointed-to object for assignment. After the assignment, number is 20. There is still one integer object, accessed through two expressions.'], code: 'int number = 10;\nint *pointer = &number;\n*pointer = 20;\nprintf("Value: %d\\n", number);\nprintf("Address: %p\\n", (void *)pointer);' },
      { heading: 'A type is not a validity certificate', paragraphs: ['An int * should refer to an appropriately aligned, live int object when you dereference it. Declaring a pointer without initializing it does not create that object. Nor does assigning an arbitrary numeric address make the memory valid. Use an existing object’s address or a properly checked allocation.', 'A null pointer deliberately refers to no object. Initialize an optional pointer to NULL and check it before use, but remember that non-null is not sufficient proof of validity. A pointer can be non-null and still point to expired or freed storage. Lifetime is a separate requirement from its numeric appearance.'] },
      { heading: 'Use pointers to update caller-owned values', paragraphs: ['A swap function receives two copied addresses, reads the first object into a temporary, and exchanges the contents. Calling swap(&a, &b) gives it access to a and b. A version that accepted two ordinary int parameters would change only its local copies.', 'This explains scanf’s &number argument: the function needs a place to store a converted value. Passing number instead provides the wrong kind of argument. Read warnings about format types carefully; they often expose a pointer mistake before it becomes a runtime failure.'], code: 'void swap(int *left, int *right) {\n    int temporary = *left;\n    *left = *right;\n    *right = temporary;\n}' },
      { heading: 'Arrays and pointers are related, not identical', paragraphs: ['In many expressions, an array converts to a pointer to its first element. Passing int values[] to a function therefore does not deliver a self-describing collection. Pass a count as well. At the array declaration site, sizeof values measures the array; inside a pointer parameter, it measures the pointer.', 'Pointer arithmetic advances in units of the pointed-to type. pointer + 1 moves to the next int when pointer points into an int array. Such arithmetic must stay within that array or its one-past position. You may use a one-past pointer as a boundary, but you may not dereference it.'] },
      { heading: 'Object lifetime controls safe access', paragraphs: ['An ordinary local variable lives until execution leaves its block. Returning its address does not extend that lifetime. The address might look unchanged afterwards, but using it to access the expired object is invalid. Return a value or write into storage owned by the caller instead.', 'Allocated storage has a different lifetime: malloc requests a block and returns NULL if it cannot satisfy the request. A successful block must eventually be released with free when no longer needed. After free, neither the original pointer nor any copied alias may be used to access that storage. Setting one pointer to NULL does not repair the other aliases.'] },
      { heading: 'Read const declarations from the object outward', paragraphs: ['const int *p allows changing p to point elsewhere, but disallows modifying the integer through p. int *const p makes p itself fixed after initialization while allowing modification of its pointed-to integer. These are different promises, and both can appear together.', 'Use const on read-only pointer parameters to communicate intent and let the compiler reject accidental writes through that interface. It does not ensure that another alias cannot modify the same object. It also does not make an invalid address safe or turn writable storage into permanent storage.'] },
      { heading: 'Debug by naming the object', paragraphs: ['When a pointer expression looks confusing, ask: which object should this designate, where was that object created, what is its type, and when does its lifetime end? Then ask whether the index or offset is within bounds. These questions are more reliable than staring at printed addresses.', 'Start with the swap example and predict each assignment before running it. Next try the structure example, where record->score means access score through a pointer to the record. Avoid using crashes as your only test: WebAssembly detects some out-of-bounds memory operations, but not every invalid C pointer operation becomes an immediate trap.'] },
    ], related: ['arrays-in-c', 'functions-in-c', 'segmentation-fault'], example: 'pointer',
  },
  {
    slug: 'common-compiler-errors', title: 'Common C Compiler Errors and How to Fix Them',
    description: 'Diagnose missing punctuation, declarations, format mismatches, linker errors, and warnings without guessing at random changes.',
    intro: 'Compiler diagnostics are evidence about where the toolchain stopped understanding your program. The highlighted location is not always the location of the original mistake. Start with the earliest meaningful message, make one focused correction, and compile again before trying to repair every later error.',
    sections: [
      { heading: 'Expected punctuation', paragraphs: ['A missing semicolon often produces a message near the following statement. The parser was still waiting for the previous statement to end. Check the line above the reported location, especially after declarations, assignments, function calls, and return statements.', 'Unmatched braces or parentheses can generate a cascade of confusing messages. Use indentation and the editor’s bracket matching to identify the intended blocks. Do not add closing punctuation at the end of the file merely until the count balances: the resulting structure may no longer match your algorithm.'], code: '/* Incorrect: printf("Hello\\n") */\n/* Correct: */\nprintf("Hello\\n");' },
      { heading: 'Undeclared identifiers and functions', paragraphs: ['An undeclared variable may be misspelled, declared after its use, or hidden outside its scope. C is case-sensitive, so total and Total are different identifiers. Moving a variable into global scope can silence one message while making the design worse; first identify where the value actually belongs.', 'For standard library functions, include the appropriate header. printf, scanf, and getchar belong to stdio.h; strlen belongs to string.h. For your own function, provide a matching declaration before the call. Modern C does not support relying on an implicit guessed function declaration.'] },
      { heading: 'Format arguments disagree', paragraphs: ['A warning that a format expects int * but receives int often identifies a missing ampersand in scanf. For output, a warning that %d receives a double means the conversion is wrong, not that printf will automatically infer your intention. Match the format to the actual argument type.', 'String storage introduces another trap. char name[32] can be passed to a bounded %31s conversion as name, without an extra ampersand. Use %zu for size_t and %p with a void * argument for pointers. Read the entire diagnostic because it usually names both the expected and supplied types.'] },
      { heading: 'Assignment versus comparison', paragraphs: ['if (value = 0) assigns zero and then tests the assigned value, which is false. if (value == 0) compares without replacing value. Both can be syntactically legal, so warnings about assignment inside a condition deserve attention.', 'A similar logic mistake is a stray semicolon after an if or loop header. while (condition); has an empty loop body. The following indented block is separate, regardless of how it looks visually. Formatting helps people, but braces and punctuation define the actual structure the compiler sees.'] },
      { heading: 'Undefined references and duplicate definitions', paragraphs: ['An undefined-symbol message during linking can mean you declared a function but never defined it, misspelled its definition, or called an unavailable library. A prototype tells the compiler how to call something; it does not create the implementation. Confirm that the target environment supplies the function.', 'Duplicate-definition errors mean more than one implementation claims the same externally visible name. In a single Circuit program, check for a second main pasted below the first. When adapting an example, replace the source or create a new program instead of appending an entire second application.'] },
      { heading: 'Separate environment limits from language mistakes', paragraphs: ['A header such as a platform-specific console or operating-system header may not exist in Circuit’s WASI toolchain. Functions for native windows, process creation, or desktop-specific keyboard input are not portable C. Removing the include will not make the missing functions available.', 'Use standard C facilities for the lesson when possible. If the goal genuinely depends on a desktop API, use an appropriate local environment. Circuit targets C17 with Clang, not every extension supported by every GCC or Windows compiler. The Docs page records the current target and limits.'] },
      { heading: 'Use a repeatable repair process', paragraphs: ['Save a backup, reproduce the error, and reduce the program to the smallest version that still fails. Read the first message and its line context. Correct the cause you can explain, then run again. If a change does not affect the failure, undo it rather than accumulating unrelated edits.', 'Once the build succeeds, test behavior separately. A program can compile cleanly yet overflow, access an array incorrectly, loop forever, or calculate the wrong result. Warnings are helpful but not a proof of correctness. Keep a few known input/output cases so that repairing one problem does not quietly change another working path.'] },
    ], related: ['c-compilation-process', 'printf-and-scanf', 'segmentation-fault'], example: 'add-two-numbers',
  },
  {
    slug: 'segmentation-fault', title: 'What Causes a Segmentation Fault in C?',
    description: 'Understand invalid memory access, array bounds, dangling pointers, stack exhaustion, and how browser WebAssembly failures differ.',
    intro: 'On many native systems, a segmentation fault is an operating-system response to an invalid memory access. It is a symptom, not a diagnosis of the exact C mistake. In Circuit, programs execute as WebAssembly, so a related failure may appear as a runtime trap instead of a native signal.',
    sections: [
      { heading: 'Memory access has a contract', paragraphs: ['A valid access needs a live object of an appropriate type at the referenced location, with the operation inside its bounds. C does not attach a complete validity history to every pointer. A pointer’s declaration alone does not prove that its current value satisfies those requirements.', 'Undefined behavior means the C language does not promise a particular outcome for that operation. It may crash immediately, corrupt a later calculation, or appear to succeed in one build. Repeatedly obtaining the expected answer is not evidence that an out-of-bounds access is allowed.'] },
      { heading: 'Array bounds are a frequent starting point', paragraphs: ['For int values[3], valid indexes are zero through two. A loop with i <= 3 writes beyond the array. Another common mistake is allocating storage for n items but indexing it with a user-provided value without validating that value first.', 'Check both the lower and upper bounds when an index is signed. Converting a negative index to an unsigned size can turn it into a very large positive value. Prefer conditions expressed directly in the same validated representation you use for the access.'], code: 'int values[3] = {10, 20, 30};\nint index = 2;\nif (index >= 0 && index < 3) {\n    printf("%d\\n", values[index]);\n}' },
      { heading: 'Uninitialized and null pointers', paragraphs: ['int *p; does not allocate an int or choose a safe object. Dereferencing p before initialization uses an indeterminate pointer. Initialize it to the address of an existing object, or use a checked allocation when dynamic storage is required.', 'NULL expresses that no object is designated. Check the result of malloc before dereferencing it. A null check is necessary in that situation, but it does not validate every possible non-null pointer. A freed pointer can remain non-null, and a pointer into the wrong object can also pass that test.'] },
      { heading: 'Lifetime mistakes survive the original scope', paragraphs: ['Returning the address of a local automatic variable leaves the caller with an address whose object has expired. A later function call may reuse that storage. The bug belongs to the returned pointer’s lifetime, not necessarily to the line where an eventual crash happens.', 'Using memory after free has the same broad problem: the old object is no longer available to you. Freeing the same allocation twice is another violation. Identify which part of the program owns each allocation and when that ownership ends. Clearing one pointer does not clear other aliases to the same released block.'] },
      { heading: 'Strings and input can cross boundaries', paragraphs: ['An unbounded scanf("%s", buffer) may write more characters than the buffer holds. strcpy also requires enough destination capacity. Use bounded input and account for the terminating null byte; a buffer of 20 bytes has room for at most 19 ordinary single-byte characters plus its terminator.', 'A string function may read beyond the object when a null terminator is missing. This is why manually filling every byte of a character array does not necessarily create a valid string. Track storage capacity and actual content length as distinct values.'] },
      { heading: 'Stack exhaustion and WebAssembly limits', paragraphs: ['Very deep recursion or very large automatic local arrays can exhaust stack space. Circuit configures a one-megabyte stack for generated programs, so a mathematically terminating recursive algorithm can still be unsuitable. Use an iterative approach or reduce the storage required by each call.', 'WebAssembly traps accesses outside its linear memory, but that boundary is not the same as every individual C object boundary. An invalid array access that lands elsewhere inside linear memory may not trap immediately. Circuit is therefore not a full memory-safety checker, and a successful run is not a substitute for bounds and lifetime reasoning.'] },
      { heading: 'Find the first invalid operation', paragraphs: ['Reduce the input, isolate the function, and inspect indexes, pointer initialization, and ownership. Add small diagnostic prints before suspicious operations, but remember that the visible crash can happen after earlier corruption. Fix the first invalid access rather than merely avoiding the final symptom.', 'For deeper native debugging, reproduce a small portable case with a local toolchain and an appropriate debugger or sanitizer build. Circuit does not currently provide an interactive memory debugger or sanitizer UI. Keep the browser test small and deterministic, and compare each access with the object’s known size and lifetime.'] },
    ], related: ['pointers-for-beginners', 'arrays-in-c', 'common-compiler-errors'], example: 'pointer',
  },
  {
    slug: 'compiler-vs-interpreter', title: 'Compiler vs Interpreter',
    description: 'Compare translation and execution strategies without assuming every language is exclusively compiled or interpreted.',
    intro: 'A compiler transforms a program into another representation. An interpreter executes a representation of a program. Real implementations often combine those ideas, so calling a language simply “compiled” or “interpreted” can hide more than it explains. C is commonly compiled ahead of execution, but the full path still depends on the target.',
    sections: [
      { heading: 'Separate a language from its implementation', paragraphs: ['A programming language defines constructs and their meaning. An implementation decides how to translate or execute valid programs on a particular platform. The same language can have more than one implementation strategy, and one implementation can change its strategy between development and production.', 'For ordinary C work, a compiler and linker produce target code before you launch the program. That is a useful practical model, not a universal rule that every possible C implementation must emit a native executable file. Circuit is a concrete alternative: Clang produces WebAssembly that a browser engine executes.'] },
      { heading: 'Ahead-of-time compilation', paragraphs: ['An ahead-of-time compiler performs translation before the relevant execution. It can report syntax and type problems without running the program and can optimize the generated representation. Native toolchains commonly produce an executable designed for a particular operating system and architecture.', 'The resulting artifact may depend on shared libraries or runtime support. “Compiled” does not mean completely self-contained. A binary built for one target will not necessarily run on another, and source portability still depends on the libraries and environmental assumptions used by the program.'] },
      { heading: 'Interpretation', paragraphs: ['An interpreter carries out program operations through another executing program. It may parse source first, build a syntax tree, or consume bytecode. The popular description “reads one source line at a time” is too narrow: interpreters frequently do substantial preparation and do not treat physical lines as execution units.', 'Interpretation can make interactive experimentation convenient, but convenience does not prove that every operation is slower or that no translation occurs. Startup work, caching, native library calls, and the workload itself all affect observed performance. Compare actual implementations rather than relying on a slogan.'] },
      { heading: 'Bytecode and just-in-time compilation', paragraphs: ['Some systems translate source to bytecode, then interpret or compile that bytecode as needed. A just-in-time compiler generates target instructions during execution, potentially using information about frequently executed paths. These approaches combine translation with runtime decisions.', 'A browser’s WebAssembly engine may use more than one compilation tier. Circuit first compiles C to a WebAssembly module; the engine then prepares that module for execution. The fact that the program runs in a browser does not mean Circuit is reading C statements and pretending to execute them in JavaScript.'] },
      { heading: 'Error timing differs, but testing remains necessary', paragraphs: ['Compilation can catch many problems before a run, including malformed syntax and incompatible declarations. It cannot generally decide whether every possible input will produce the intended result. A division, index, or loop condition may only become problematic for a particular runtime value.', 'Interpreted systems can also reject source before executing its first meaningful operation. Conversely, compiled programs can fail after hours of execution. Classify errors by the actual stage and operation, not by assuming that all mistakes in one category happen early or late.'] },
      { heading: 'Performance has several costs', paragraphs: ['For a short interactive exercise, downloading a toolchain and compiling a module may take longer than running the algorithm. For a long-running numerical task, generated code quality and memory access patterns may dominate. Measure startup, translation, and execution separately when those distinctions matter.', 'Optimization levels can also change translation time and runtime behavior for valid programs. An optimized build is not automatically easier to debug, and undefined behavior can become more visible under optimization. Circuit currently uses -O0 for its C compilation, so its timings are not a benchmark for every possible Clang configuration.'] },
      { heading: 'Choose tools around the job', paragraphs: ['For learning C expressions, functions, and standard input, a browser compiler offers a short setup path. For large projects, native dependencies, deep debugging, or operating-system integration, a local toolchain offers a different set of capabilities. Neither choice makes the underlying learning more or less legitimate.', 'Try the same small function with known inputs in both environments if you have them. Compare results before comparing speed, and check target differences such as type sizes and available APIs. The useful question is which implementation supports your task and constraints, not which label sounds more powerful.'] },
    ], related: ['how-a-c-compiler-works', 'online-compiler-vs-gcc'], example: 'function',
  },
  {
    slug: 'online-compiler-vs-gcc', title: 'Online C Compiler vs Installing GCC',
    description: 'Compare Circuit’s online C compiler with a desktop GCC toolchain based on setup, files, debugging, portability, and system access.',
    intro: 'A browser compiler is useful when you want to start a short C exercise immediately. A desktop toolchain is useful when the environment itself becomes part of the project. The right choice depends on what you need to build, not on whether one approach is universally better.',
    sections: [
      { heading: 'What an online compiler can mean', paragraphs: ['Some online compilers send source to a remote service. Circuit instead downloads a Clang/WebAssembly toolchain and compiles on your device in a worker. Its visible terminal is connected to the real running program. This distinction matters for privacy, network dependence, and available system capabilities.', 'Circuit is not GCC running on a remote Linux machine. It uses Clang with a WASI target and C17 settings. Much standard C teaching code works across both compilers, but compiler extensions, platform headers, and assumptions about native APIs can differ. Check the actual target before drawing conclusions from one successful build.'] },
      { heading: 'Start quickly with a browser workspace', paragraphs: ['For a greeting, loop, array exercise, or small function, Circuit removes installation steps. Create a .c program, edit it, and press Run. Interactive scanf and getchar input arrives through the terminal. Programs autosave locally and can be exported as backups or downloaded individually.', 'The first run needs compiler assets from the site and can be slower than later runs. A supported browser must provide WebAssembly, workers, SharedArrayBuffer, and cross-origin isolation. Browser restrictions or blocked downloads can prevent initialization even when your C source is valid. There is no fallback remote compiler.'] },
      { heading: 'Know the boundaries before choosing an exercise', paragraphs: ['Circuit currently compiles a single source file with standard WASI libraries. It is suitable for short learning programs, not a full project build system. Native GUI frameworks, arbitrary process creation, networking APIs, and operating-system-specific console functions are outside that environment.', 'File I/O uses a temporary in-memory directory for each run. A file created by fopen is not a file on your computer and does not become an IndexedDB program. Use the File Handling example to explore streams, but choose a desktop environment when the goal requires persistent disk files or interaction with existing directories.'] },
      { heading: 'What a local GCC installation adds', paragraphs: ['A local toolchain gives you direct control over compiler options, target libraries, source files, and the build process. You can integrate a debugger, use a build system, inspect object files, and work with the operating system’s file and process facilities when permitted.', 'Installation instructions depend on your operating system and package manager. Use the official instructions for the environment you choose, then confirm gcc --version and compile a tiny known program before setting up a large project. The commands belong in a shell, not inside Circuit’s C editor.'] },
      { heading: 'Compare storage and privacy accurately', paragraphs: ['Circuit’s saved library belongs to the browser profile and site origin. It does not synchronize to an account. Clearing site data, using another browser, or moving from crunner.pages.dev to a custom domain can leave you with a different library. Export before changing environments.', 'A desktop source file belongs to the filesystem where you save it, with whatever backup or synchronization tools you configure. Neither browser storage nor an unbacked-up local folder guarantees recovery. Also distinguish source handling from web hosting: visiting Circuit still requests website assets from its hosting provider even though compilation stays local.'] },
      { heading: 'Understand limits and measurements', paragraphs: ['Circuit stops programs after its active execution allowance and uses separate stdin-idle and overall-session limits. It also bounds memory, source size, and output. These controls keep mistakes such as infinite loops from monopolizing the interface. See Docs for the exact current values rather than assuming a desktop process limit applies.', 'A local executable has different resource controls, target code, and I/O behavior. Do not use one tiny browser timing as a fair benchmark of GCC versus Clang. First ensure the same algorithm, inputs, optimization settings, and target assumptions, then measure the costs relevant to your actual application.'] },
      { heading: 'Move between them without throwing work away', paragraphs: ['Learn a concept in a small Circuit program, download the .c file, and build it locally when you need deeper tooling. Keep code close to standard C to reduce avoidable differences. If a program stops building, inspect the diagnostic and the unavailable interface rather than rewriting the whole algorithm.', 'Use Circuit for fast experiments and reproducible examples; use a local project for multi-file development, persistent files, specialized libraries, and advanced debugging. The two can support the same learning process. A clean, well-tested function is useful in either environment.'] },
    ], related: ['compiler-vs-interpreter', 'c-compilation-process'], example: 'file-handling',
  },
  {
    slug: 'basic-c-examples', title: 'Basic C Program Examples',
    description: 'Build a learning sequence from greetings and conditions to loops, arrays, functions, pointers, and structures with testable C examples.',
    intro: 'Examples are most useful when you predict what they will do, explain why, and change them deliberately. Running a copied program once proves very little about your understanding. Use the examples library as a set of small experiments, with one new concept and a few known test cases at each step.',
    sections: [
      { heading: 'Begin with output and simple input', paragraphs: ['Hello World introduces headers, main, a function call, and a newline. Change the output text, add a second line, and identify which characters belong to the source syntax versus the printed message. Keep the working program as a reference before adding input.', 'Add Two Numbers introduces variables, addresses, and scanf return values. Test two positives, one negative, and zero. The example limits ordinary numeric inputs before adding them. For production-style parsing of arbitrary text, use a bounded line and explicit conversion checks instead of assuming every user types a representable integer.'] },
      { heading: 'Conditions should cover boundaries', paragraphs: ['Even or Odd uses remainder by two. Test zero and negative numbers as well as positive ones; checking for a remainder of exactly one is not the right general test for oddness. Largest of Three starts with the first actual input as its candidate, which allows all-negative cases to work.', 'Write the expected answer before running each case. A useful test set targets branch boundaries: equal values, the smallest accepted value, and inputs just outside a chosen range. Repeating many ordinary positive cases can miss a single incorrect comparison that matters at the edge.'] },
      { heading: 'Loops need a state and a stopping rule', paragraphs: ['Factorial maintains a product and advances a counter. Fibonacci maintains the previous two terms. A multiplication table advances through an inclusive range. For each example, identify initialization, the continuation condition, and the update that guarantees progress.', 'Check how the program behaves when the loop runs zero times, once, and several times. The factorial example keeps its input small enough for the chosen integer type. Extending a loop bound is not enough to extend the mathematical range: arithmetic storage can overflow before the algorithm finishes.'], code: '/* Trace total after each iteration: 1, 3, 6, 10. */\nint total = 0;\nfor (int value = 1; value <= 4; ++value) {\n    total += value;\n}\nprintf("%d\\n", total);' },
      { heading: 'Digit exercises expose representation choices', paragraphs: ['Reverse a Number repeatedly extracts the final digit with % 10 and removes it with integer division. Palindrome keeps an untouched copy and compares it with the reversed result. Both examples deliberately accept a bounded nonnegative range.', 'Reversing an integer discards leading zeroes in the result. If the task is to reverse a written identifier such as 00120 while preserving every character, use a string instead. A problem statement’s data model matters before you choose a loop. Numbers and digit strings can look alike while requiring different behavior.'] },
      { heading: 'Move from individual values to collections', paragraphs: ['Array Sum introduces a count-controlled traversal. Array Reverse pairs indexes from opposite ends and stops halfway. Matrix Addition uses nested loops with independent row and column bounds. Test small distinctive data so that a swapped index or skipped element is visible.', 'String Length demonstrates a different boundary: the first null terminator. The character array has capacity for that terminator in addition to visible text. Do not assume every byte array is a valid string or that a string’s byte length equals its number of displayed characters in every encoding.'] },
      { heading: 'Extract behavior into functions', paragraphs: ['Once a calculation works, move it into a function with explicit parameters and a return value. Keep prompting and printing in main at first. The Function example computes a square; the Pointer example swaps caller-owned values using copied addresses.', 'The Structure example groups related fields into one record. Dot and arrow access show the difference between a structure object and a pointer to it. These examples connect earlier ideas rather than replacing them: arrays still need bounds, pointers still need live objects, and functions still need clear contracts.'] },
      { heading: 'Use the library as a practice routine', paragraphs: ['Open an example page, read its explanation and sample input, and select Try in Circuit. It creates a new program rather than replacing an existing file. Predict the sample output, run it, then change one condition or value and explain the new result. Save useful variations under descriptive names.', 'Finish each exercise with one ordinary case, one boundary case, and one rejected input where relevant. If a run fails, decide whether the issue is translation, input, resource limits, or logic. The File Handling example is a useful final reminder that environment matters: its runtime file is temporary and does not survive another execution.'] },
    ], related: ['first-c-program', 'arrays-in-c', 'functions-in-c'], example: 'multiplication-table',
  },
];
